function validate([nums]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => v < -1000000000 || v > 1000000000)) return 'Each value is between -10^9 and 10^9.';
  const sorted = [...nums].sort((a, b) => a - b);
  let moves = 0;
  for (let i = 0; i < sorted.length / 2; i++) moves += sorted[sorted.length - 1 - i] - sorted[i];
  if (moves > 2147483647) return 'The answer must fit in a 32-bit integer; use values closer together.';
  return null;
}

