function minMoves2(nums) {
  nums.sort((a, b) => a - b);
  let left = 0;
  let right = nums.length - 1;
  let moves = 0;
  while (left < right) {
    moves += nums[right] - nums[left];
    left++;
    right--;
  }
  return moves;
}

