function minMoves2(nums) {
  // The best target is one of the values; try each and sum the distances.
  let best = Infinity;
  for (const target of nums) {
    let cost = 0;
    for (const value of nums) cost += Math.abs(value - target);
    best = Math.min(best, cost);
  }
  return best;
}

